button[type="submit"]:hover {
  background-color: #a370f7;
}

button[type="submit"]:focus {
  outline: 2px solid var(--text-color);
  outline-offset: 2px;
}

.required-star {
  color: var(--error-color);
  margin-left: 2px;
}
