const FormField = ({ id, label, type = "text", value, onChange, error, required, helperText, autocomplete }) => {
  const isInvalid = !!error;
  const describedBy = [
    helperText ? `${id}-helper` : null,
    error ? `${id}-error` : null
  ].filter(Boolean).join(' ');

  return (
    <div className="form-field">
      <label htmlFor={id}>
        {label}
        {required && <span className="required-star" aria-hidden="true">*</span>}
      </label>
      <input
        id={id}
        name={id}
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        required={required}
        aria-required={required}
        aria-invalid={isInvalid}
        aria-describedby={describedBy || undefined}
        autoComplete={autocomplete}
      />
      {helperText && <div id={`${id}-helper`} className="helper-text">{helperText}</div>}
      <div id={`${id}-error`} className="error-message" role="alert">
        {error ? `Error: ${error}` : ''}
      </div>
    </div>
  );
};

const ContactForm = () => {
  const [values, setValues] = useState({
    fullName: '',
    email: '',
    phone: ''
  });
  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const fullNameRef = useRef(null);
  const emailRef = useRef(null);
  const phoneRef = useRef(null);

  const validate = (name, value) => {
    if (name === 'fullName') {
      if (!value.trim()) return 'Full name is required.';
    }
    if (name === 'email') {
      if (!value.trim()) return 'Email address is required.';
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(value)) return 'Please enter a valid email address.';
    }
    if (name === 'phone' && value.trim()) {
      // Optional, but if present should look like a phone number
      const phoneRegex = /^\+?[\d\s\-()]{7,20}$/;
      if (!phoneRegex.test(value)) return 'Please enter a valid phone number format.';
    }
    return '';
  };

  const handleChange = (name, value) => {
    setValues(prev => ({ ...prev, [name]: value }));
    const error = validate(name, value);
    setErrors(prev => ({ ...prev, [name]: error }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    const newErrors = {
      fullName: validate('fullName', values.fullName),
      email: validate('email', values.email),
      phone: validate('phone', values.phone)
    };

    setErrors(newErrors);

    const firstErrorField = Object.keys(newErrors).find(key => newErrors[key]);
    if (firstErrorField) {
      document.getElementById(firstErrorField).focus();
      return;
    }

    setSubmitted(true);
    console.log('Form submitted:', values);
  };

  if (submitted) {
    return (
      <div className="support-page" role="status" aria-live="polite">
        <h1>Thank you!</h1>
        <p>Your support request has been received. We'll get back to you shortly.</p>
        <button onClick={() => setSubmitted(false)} className="submit-button" style={{marginTop: '1rem'}}>
          Send another message
        </button>
      </div>
    );
  }

  return (
    <div className="support-page">
      <h1>Contact Support</h1>
      <p className="helper-text" style={{marginBottom: '1.5rem'}}>
        Fields marked with <span className="required-star" aria-hidden="true">*</span> are required.
      </p>
      <form onSubmit={handleSubmit} noValidate>
        <FormField
          id="fullName"
          label="Full Name"
          value={values.fullName}
          onChange={(val) => handleChange('fullName', val)}
          error={errors.fullName}
          required
          autocomplete="name"
        />
        <FormField
          id="email"
          label="Email Address"
          type="email"
          value={values.email}
          onChange={(val) => handleChange('email', val)}
          error={errors.email}
          required
          autocomplete="email"
        />
        <FormField
          id="phone"
          label="Phone Number"
          type="tel"
          value={values.phone}
          onChange={(val) => handleChange('phone', val)}
          error={errors.phone}
          helperText="Format: +1 123-456-7890 (optional)"
          autocomplete="tel"
        />
        <button type="submit">Send Message</button>
      </form>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ContactForm />);
